(function(root,factory){const api=factory();if(typeof module==="object"&&module.exports)module.exports=api;root.OneBoxReaderEnhancementCore=api;})(typeof globalThis!=="undefined"?globalThis:this,function(){
'use strict';
const validDay=value=>/^\d{4}-\d{2}-\d{2}$/.test(String(value||''));
function validTotals(value,cap){const out={};for(const[key,val]of Object.entries(value||{})){if(!key)continue;const n=Math.max(0,Math.min(cap,Math.floor(Number(val)||0)));if(n)out[String(key).slice(0,120)]=n;}return out;}
function normalizeStats(value){const source=value&&typeof value==='object'?value:{},devices={};if(source.devices&&typeof source.devices==='object'){for(const[id,entry]of Object.entries(source.devices)){if(!id||id.length>120||!entry||typeof entry!=='object')continue;const days={};for(const[day,val]of Object.entries(entry.days||{})){const n=Math.max(0,Math.min(86400,Math.floor(Number(val)||0)));if(validDay(day)&&n)days[day]=n;}devices[id]={days,books:validTotals(entry.books,86400*366)};}}else if(source.days||source.books){devices.legacy={days:Object.fromEntries(Object.entries(source.days||{}).filter(([d])=>validDay(d)).map(([d,v])=>[d,Math.max(0,Math.min(86400,Math.floor(Number(v)||0)))])),books:validTotals(source.books,86400*366)};}return{devices,updatedAt:Math.max(0,Number(source.updatedAt)||0)};}
function addSeconds(value,day,bookId,seconds,deviceId='local'){const stats=normalizeStats(value);if(!validDay(day)||!bookId)return stats;const amount=Math.max(0,Math.min(300,Math.floor(Number(seconds)||0)));if(!amount)return stats;const id=String(deviceId||'local').slice(0,120),device=stats.devices[id]||(stats.devices[id]={days:{},books:{}});device.days[day]=Math.min(86400,(device.days[day]||0)+amount);const book=String(bookId).slice(0,120);device.books[book]=(device.books[book]||0)+amount;stats.updatedAt=Date.now();return stats;}
function mergeStats(localValue,remoteValue){const left=normalizeStats(localValue),right=normalizeStats(remoteValue),devices={};for(const id of new Set([...Object.keys(left.devices),...Object.keys(right.devices)])){const a=left.devices[id]||{days:{},books:{}},b=right.devices[id]||{days:{},books:{}};const maxMap=(x,y)=>Object.fromEntries([...new Set([...Object.keys(x||{}),...Object.keys(y||{})])].map(k=>[k,Math.max(Number(x?.[k])||0,Number(y?.[k])||0)]).filter(([,v])=>v));devices[id]={days:maxMap(a.days,b.days),books:maxMap(a.books,b.books)};}return{devices,updatedAt:Math.max(left.updatedAt,right.updatedAt)};}
function aggregateStats(value){const devices=normalizeStats(value).devices,days={},books={};for(const device of Object.values(devices)){for(const[key,seconds]of Object.entries(device.days))days[key]=(days[key]||0)+seconds;for(const[key,seconds]of Object.entries(device.books))books[key]=(books[key]||0)+seconds;}return{days,books,total:Object.values(days).reduce((a,b)=>a+b,0)};}
function recentDays(endDate,count=35){const end=new Date(endDate);end.setHours(12,0,0,0);const size=Math.max(1,Math.min(366,Number(count)||35));return Array.from({length:size},(_,i)=>{const d=new Date(end);d.setDate(d.getDate()-(size-1-i));return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');});}
function safeHttpUrl(value,base){try{const url=new URL(String(value||''),base||undefined);return['http:','https:'].includes(url.protocol)?url.href:'';}catch{return'';}}
function safeTemplateUrl(value,base){const tokens=[];const protectedValue=String(value||'').replace(/\{[^{}]+\}/g,token=>{const key='__ONEBOX_TEMPLATE_'+tokens.length+'__';tokens.push([key,token]);return key});let result=safeHttpUrl(protectedValue,base);if(!result)return'';for(const[key,token]of tokens)result=result.replace(key,token);return result;}
function mergeCatalogs(localValue,remoteValue){const map=new Map();for(const item of [...(Array.isArray(localValue)?localValue:[]),...(Array.isArray(remoteValue)?remoteValue:[])]){const url=safeHttpUrl(item?.url);if(url)map.set(url,{...(map.get(url)||{}),...item,url});}return[...map.values()].slice(0,200);}
function expandSearchTemplate(template,query){const value=String(query||'');let result=String(template||'').replace(/\{([?&])([^}]+)\}/g,(_,operator,names)=>(operator==='?'?'?':'&')+names.split(',').map(name=>{const key=name.replace(/\*$/, '').replace(/\?$/, '');const content=/search|query|title|term|text|q/i.test(key)?value:'';return encodeURIComponent(key)+'='+encodeURIComponent(content)}).join('&'));result=result.replace(/\{([^}]+)\}/g,(_,name)=>encodeURIComponent(/search|query|title|term|text|q/i.test(name.replace(/[?*]$/,''))?value:''));return safeHttpUrl(result);}
return{normalizeStats,addSeconds,mergeStats,aggregateStats,mergeCatalogs,recentDays,safeHttpUrl,safeTemplateUrl,expandSearchTemplate,validDay};
});